ALTER TABLE invitations ADD COLUMN registration_starts_at DATETIME NULL AFTER event_at, ADD COLUMN registration_ends_at DATETIME NULL AFTER registration_starts_at, ADD COLUMN capacity INT UNSIGNED NULL AFTER registration_ends_at, ADD COLUMN waitlist_enabled TINYINT(1) NOT NULL DEFAULT 0 AFTER capacity, ADD KEY idx_invitations_registration(church_id,registration_starts_at,registration_ends_at);
ALTER TABLE invitation_applications ADD COLUMN attendance_status ENUM('not_checked','attended','absent') NOT NULL DEFAULT 'not_checked' AFTER status, ADD COLUMN is_waitlisted TINYINT(1) NOT NULL DEFAULT 0 AFTER attendance_status, ADD COLUMN answers_json JSON NULL AFTER message;
CREATE TABLE invitation_form_questions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,church_id BIGINT UNSIGNED NOT NULL,invitation_id BIGINT UNSIGNED NOT NULL,label VARCHAR(190) NOT NULL,question_type ENUM('text','textarea','select','checkbox') NOT NULL DEFAULT 'text',options_json JSON NULL,is_required TINYINT(1) NOT NULL DEFAULT 0,is_active TINYINT(1) NOT NULL DEFAULT 1,sort_order SMALLINT UNSIGNED NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_questions_tenant(church_id,invitation_id,sort_order),CONSTRAINT fk_questions_church FOREIGN KEY(church_id) REFERENCES churches(id) ON DELETE CASCADE,CONSTRAINT fk_questions_invitation FOREIGN KEY(invitation_id) REFERENCES invitations(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
